@Override
public CacheStrategy<ResultRow, Object, GroupByQuery> getCacheStrategy(final GroupByQuery query)
{
  return new CacheStrategy<ResultRow, Object, GroupByQuery>()
  {
    private static final byte CACHE_STRATEGY_VERSION = 0x1;
    private final List<AggregatorFactory> aggs = query.getAggregatorSpecs();
    private final List<DimensionSpec> dims = query.getDimensions();

    @Override
    public boolean isCacheable(GroupByQuery query, boolean willMergeRunners, boolean bySegment)
    {
      //disable segment-level cache on borker,
      //see PR https://github.com/apache/druid/issues/3820
      return willMergeRunners || !bySegment;
    }

    @Override
    public byte[] computeCacheKey(GroupByQuery query)
    {
      CacheKeyBuilder builder = new CacheKeyBuilder(GROUPBY_QUERY)
          .appendByte(CACHE_STRATEGY_VERSION)
          .appendCacheable(query.getGranularity())
          .appendCacheable(query.getDimFilter())
          .appendCacheables(query.getAggregatorSpecs())
          .appendCacheables(query.getDimensions())
          .appendCacheable(query.getVirtualColumns());
      if (query.isApplyLimitPushDown()) {
        builder.appendCacheable(query.getLimitSpec());
      }
      return builder.build();
    }

    @Override
    public byte[] computeResultLevelCacheKey(GroupByQuery query)
    {
      final CacheKeyBuilder builder = new CacheKeyBuilder(GROUPBY_QUERY)
          .appendByte(CACHE_STRATEGY_VERSION)
          .appendCacheable(query.getGranularity())
          .appendCacheable(query.getDimFilter())
          .appendCacheables(query.getAggregatorSpecs())
          .appendCacheables(query.getDimensions())
          .appendCacheable(query.getVirtualColumns())
          .appendCacheable(query.getHavingSpec())
          .appendCacheable(query.getLimitSpec())
          .appendCacheables(query.getPostAggregatorSpecs());

      if (query.getSubtotalsSpec() != null && !query.getSubtotalsSpec().isEmpty()) {
        for (List<String> subTotalSpec : query.getSubtotalsSpec()) {
          builder.appendStrings(subTotalSpec);
        }
      }
      return builder.build();
    }

    @Override
    public TypeReference<Object> getCacheObjectClazz()
    {
      return OBJECT_TYPE_REFERENCE;
    }

    @Override
    public Function<ResultRow, Object> prepareForCache(boolean isResultLevelCache)
    {
      final boolean resultRowHasTimestamp = query.getResultRowHasTimestamp();

      return new Function<ResultRow, Object>()
      {
        @Override
        public Object apply(ResultRow resultRow)
        {
          final List<Object> retVal = new ArrayList<>(1 + dims.size() + aggs.size());
          int inPos = 0;

          if (resultRowHasTimestamp) {
            retVal.add(resultRow.getLong(inPos++));
          } else {
            retVal.add(query.getUniversalTimestamp().getMillis());
          }

          for (int i = 0; i < dims.size(); i++) {
            retVal.add(resultRow.get(inPos++));
          }
          for (int i = 0; i < aggs.size(); i++) {
            retVal.add(resultRow.get(inPos++));
          }
          if (isResultLevelCache) {
            for (int i = 0; i < query.getPostAggregatorSpecs().size(); i++) {
              retVal.add(resultRow.get(inPos++));
            }
          }
          return retVal;
        }
      };
    }

    @Override
    public Function<Object, ResultRow> pullFromCache(boolean isResultLevelCache)
    {
      return new Function<Object, ResultRow>()
      {
        private final Granularity granularity = query.getGranularity();

        @Override
        public ResultRow apply(Object input)
        {
          final List<Object> cachedValues = (List<Object>) input;
          final Iterator<Object> results = cachedValues.iterator();
          final Object rawTimestamp = results.next();
          final long timestampMillis = ((Number) rawTimestamp).longValue();
          final DateTime timestamp = granularity.toDateTime(timestampMillis);

          final DateTime universalTimestamp = query.getUniversalTimestamp();
          final boolean resultRowHasTimestamp = universalTimestamp == null;
          final List<DimensionSpec> queryDimensions = query.getDimensions();
          final List<AggregatorFactory> queryAggregators = query.getAggregatorSpecs();
          final int dimensionCount = queryDimensions.size();
          final int aggregatorCount = queryAggregators.size();
          final int postAggregatorCount = query.getPostAggregatorSpecs().size();
          final int dimensionStart = resultRowHasTimestamp ? 1 : 0;
          final int aggregatorStart = dimensionStart + dimensionCount;
          final int postAggregatorStart = aggregatorStart + aggregatorCount;
          final int size;
          if (isResultLevelCache) {
            size = postAggregatorStart + postAggregatorCount;
          } else {
            size = postAggregatorStart;
          }

          final ResultRow resultRow = ResultRow.create(size);
          if (resultRowHasTimestamp) {
            resultRow.set(0, timestamp.getMillis());
          }

          final Iterator<DimensionSpec> dimsIter = queryDimensions.iterator();
          int dimPos = 0;
          while (dimsIter.hasNext() && results.hasNext()) {
            final DimensionSpec dimensionSpec = dimsIter.next();
            final Object rawDimensionValue = results.next();
            final ColumnType outputType = dimensionSpec.getOutputType();
            final Object convertedDimensionValue;
            if (outputType == null) {
              throw new NullPointerException("type");
            } else {
              final ValueType valueType = outputType.getType();
              if (valueType == ValueType.LONG) {
                if (rawDimensionValue == null) {
                  convertedDimensionValue = null;
                } else {
                  if (rawDimensionValue instanceof Long) {
                    convertedDimensionValue = (Long) rawDimensionValue;
                  } else {
                    if (rawDimensionValue instanceof Number) {
                      convertedDimensionValue = ((Number) rawDimensionValue).longValue();
                    } else if (rawDimensionValue instanceof Boolean) {
                      convertedDimensionValue = Evals.asLong((Boolean) rawDimensionValue);
                    } else if (rawDimensionValue instanceof String) {
                      convertedDimensionValue = DimensionHandlerUtils.getExactLongFromDecimalString(
                          (String) rawDimensionValue
                      );
                    } else {
                      convertedDimensionValue = DimensionHandlerUtils.convertObjectToLong(
                          rawDimensionValue,
                          false
                      );
                    }
                  }
                }
              } else if (valueType == ValueType.FLOAT) {
                if (rawDimensionValue == null) {
                  convertedDimensionValue = null;
                } else {
                  if (rawDimensionValue instanceof Float) {
                    convertedDimensionValue = (Float) rawDimensionValue;
                  } else {
                    if (rawDimensionValue instanceof Number) {
                      convertedDimensionValue = ((Number) rawDimensionValue).floatValue();
                    } else if (rawDimensionValue instanceof String) {
                      convertedDimensionValue = Floats.tryParse((String) rawDimensionValue);
                    } else {
                      convertedDimensionValue = DimensionHandlerUtils.convertObjectToFloat(
                          rawDimensionValue,
                          false
                      );
                    }
                  }
                }
              } else if (valueType == ValueType.DOUBLE) {
                if (rawDimensionValue == null) {
                  convertedDimensionValue = null;

metadata.output:
          }

          return runner.run(
              queryPlus.withQuery(groupByQuery.withDimensionSpecs(dimensionSpecs)),
              responseContext
          );
        }
      }
  );
}

