                                      ? FrameWriterUtils.replaceUnknownTypesWithNestedColumns(rowSignature)
                                      : rowSignature;

  FrameWriterFactory frameWriterFactory = FrameWriters.makeFrameWriterFactory(
      FrameType.COLUMNAR,
