  Sequence<Frame> frames = FrameCursorUtils.cursorToFrames(cursor, frameWriterFactory).withBaggage(closeble);

  return Optional.of(frames.map(frame -> new FrameSignaturePair(frame, modifiedRowSignature)));
}

